def analyze_argument(sentence):
    # Split the sentence into individual words
    words = sentence.split()

    # Initialize variables to track current claim/premise and whether we've started a new claim/premise
    current_claim = False
    current_premise = False

    # Initialize lists to store claims and premises
    claims = []
    premises = []

    # Iterate over each word in the sentence
    for i, word in enumerate(words):
        # Check if the word indicates a claim or premise
        if word.lower() in ['because','since']:
            current_claim = True
            current_premise = False
        elif word.lower() in ['but', 'however']:
            current_claim = False
            current_premise = True
        else:
            # If we're currently processing a claim, check if the next word could be part of it
            if current_claim:
                if i + 1 < len(words) and words[i+1].lower() == 'what':
                    claims.append(' '.join(words[:i]))
                    current_claim = False
                elif i > 0 and words[i-1].lower() == 'who' and words[i].lower() == 'are':
                    claims.append(' '.join(words[:i]))
                    current_claim = False
            # If we're currently processing a premise, check if the next word could be part of it
            elif current_premise:
                if i + 1 < len(words) and words[i+1].lower() == 'there':
                    premises.append(' '.join(words[:i]))
                    current_premise = False

        # Add the current word to the list of claims or premises
        if current_claim:
            claims.append(word)
        elif current_premise:
            premises.append(word)

    # Create the final output string
    output = ''
    for i, word in enumerate(words):
        if word in claims:
            output += '<claim>' + word + '</claim>'
        elif word in premises:
            output += '<premise>' + word + '</premise>'
        else:
            output += word +''

    return output.strip()

