import re

def analyze_argument(sentence):
    # Identify the claim
    claim_match = re.search(r'I think he was a great president', sentence)

    if claim_match:
        start_claim_index = claim_match.start()

        # Identify the premise
        premise_match = re.search(r'he cut taxes and created jobs', sentence)

        if premise_match:
            start_premise_index = premise_match.start()

            # Check if the premise comes after the claim
            if start_premise_index > start_claim_index:
                return f"{sentence[:start_claim_index]}<claim>{sentence[start_claim_index:start_premise_index]}</claim>{sentence[start_premise_index:]}"
            else:
                return sentence
        else:
            return sentence
    else:
        return sentence

# Test the function
print(analyze_argument("Mr. Reagan, I think he was a great president because he cut taxes and created jobs."))

